import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {spawnSync} from 'node:child_process';

// Independent oracle, written from the ticket contract. Never imports production code.
const root=process.cwd(), work=path.join(root,'games/typing-defense/tmp/codex-231/atlas-audit');
const tree=path.join(root,'games/typing-defense/tmp/codex-231/tree');
const pending=process.argv.includes('--pending');
const base=pending?path.join(work,'pending'):path.join(tree,'public/assets/typing-defense/scenery');
const magick='/opt/homebrew/bin/magick';
const read=p=>JSON.parse(fs.readFileSync(p,'utf8'));
const manifest=read(path.join(base,'manifest.json'));
const prior=read(path.join(root,'docs/codex-queue/199',pending?'pending-edge-failures.json':'edge-failures.json'));
const priorMetrics=pending?read(path.join(root,'docs/codex-queue/199/pending-metrics.json')):null;
const pushes=read(path.join(root,'docs/codex-queue/199/media-push.json'));
const budget=read(path.join(root,'docs/codex-queue/199/media-budget-after.json'));
const hash=(b,algo='sha256')=>crypto.createHash(algo).update(b).digest('hex');
function run(args){const p=spawnSync(magick,args,{maxBuffer:100*1024*1024});if(p.status!==0)throw Error(p.stderr.toString());return p.stdout;}

// Two raster scans of 8-connected unit edges give exact Chebyshev distance.
// Distances start at zero on the target mask. No function comes from ticket199.
function distance(mask,w,h,target){
 const d=new Uint16Array(w*h);for(let i=0;i<d.length;i++) d[i]=mask[i]===target?0:65500;
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){
  const i=y*w+x;let n=d[i];
  if(x)n=Math.min(n,d[i-1]+1);
  if(y){n=Math.min(n,d[i-w]+1);if(x)n=Math.min(n,d[i-w-1]+1);if(x+1<w)n=Math.min(n,d[i-w+1]+1);}
  d[i]=n;
 }
 for(let y=h-1;y>=0;y--)for(let x=w-1;x>=0;x--){
  const i=y*w+x;let n=d[i];
  if(x+1<w)n=Math.min(n,d[i+1]+1);
  if(y+1<h){n=Math.min(n,d[i+w]+1);if(x)n=Math.min(n,d[i+w-1]+1);if(x+1<w)n=Math.min(n,d[i+w+1]+1);}
  d[i]=n;
 }
 return d;
}
function hsv(r,g,b){
 const hi=Math.max(r,g,b),lo=Math.min(r,g,b),delta=hi-lo;
 let h=0;if(delta){if(hi===r)h=(g-b)/delta;else if(hi===g)h=2+(b-r)/delta;else h=4+(r-g)/delta;h=((h*60)%360+360)%360;}
 return [h,hi?delta/hi:0,hi/255];
}
function keylike(r,g,b,key){
 const target=key.match(/[0-9a-f]{2}/gi).map(v=>parseInt(v,16));
 if(Math.max(Math.abs(r-target[0]),Math.abs(g-target[1]),Math.abs(b-target[2]))<=60)return true;
 const [h,s]=hsv(r,g,b),kh=hsv(...target)[0],delta=Math.abs(h-kh);
 return Math.min(delta,360-delta)<=20&&s>.5;
}
function crop(data,size,rect){
 const [x0,y0,x1,y1]=rect,w=x1-x0,h=y1-y0,out=Buffer.alloc(w*h*4);
 for(let y=0;y<h;y++)data.copy(out,y*w*4,((y+y0)*size+x0)*4,((y+y0)*size+x1)*4);
 return {data:out,w,h};
}
function bruteDistance(mask,w,h,x,y,target,cap=9){
 if(mask[y*w+x]===target)return 0;
 for(let radius=1;radius<=cap;radius++)for(let yy=Math.max(0,y-radius);yy<=Math.min(h-1,y+radius);yy++)for(let xx=Math.max(0,x-radius);xx<=Math.min(w-1,x+radius);xx++)if(Math.max(Math.abs(xx-x),Math.abs(yy-y))===radius&&mask[yy*w+xx]===target)return radius;
 return cap+1;
}
const result={ngay:'2026-10-30',bo:pending?'pending26, chưa được nhận và không thuộc runtime':'runtime8 đã nhận',phuongPhap:'Giải mã ImageMagick RGBA8; khoảng cách Chebyshev hai lượt quét độc lập; 2px trong và 8/4px ngoài; V<.25 miễn trước, alpha0 cách>=3 và luma<.2 miễn sau.',files:[],sprites:[],totals:{},checks:{}};
const decoded=new Map();
for(const [rel,expectedSha] of Object.entries(manifest.build.outputs)){
 const file=path.join(base,rel),bytes=fs.readFileSync(file),meta=run(['identify','-format','%w %h %[channels]',file]).toString().trim().split(' ');
 const [w,h]=meta.map(Number),data=run([file,'-depth','8','rgba:-']);
 if(data.length!==w*h*4)throw Error('bad raw length '+rel);
 fs.writeFileSync(path.join(work,path.basename(rel)+'.rgba'),data);
 const reference=pushes.find(v=>v.path.endsWith('/'+rel));
 const expectedSize=rel.includes('medium')?2048:rel.includes('shadow')?1024:4096;
 result.files.push({file:rel,bytes:bytes.length,width:w,height:h,channels:meta.slice(2).join(' '),sha256:hash(bytes),md5:hash(bytes,'md5'),manifestShaMatch:hash(bytes)===expectedSha,mediaPushMatch:pending?null:!!reference&&reference.bytes===bytes.length&&reference.md5===hash(bytes,'md5')&&reference.sha256===hash(bytes),pendingReportBytesShaMatch:pending?priorMetrics.files[rel].bytes===bytes.length&&priorMetrics.files[rel].sha256===hash(bytes):null,dimensionsMatch:w===expectedSize&&h===expectedSize});
 decoded.set(rel,{data,w,h});
 console.log('decoded',rel,w,h,bytes.length);
}
const allFailure=[],raws=new Map();
const q95=prior.attempts.find(v=>v.quality===95);
for(const tier of ['high','medium']){
 const scale=tier==='high'?1:.5,size=manifest.tiers[tier].size;
 const color=decoded.get(manifest.tiers[tier].color).data,normal=decoded.get(manifest.tiers[tier].normal).data;
 const sums={keyCandidates:0,darkExempt:0,alpha0Exempt:0,alpha0AlsoDark:0,failures:0,cutoffRetained:0,bruteChecks:0,bruteMismatches:0};
 for(const s of manifest.sprites){
  const rect=s.rect.map(v=>v*scale),{data,w,h}=crop(color,size,rect),n=crop(normal,size,rect).data,mask=new Uint8Array(w*h);
  for(let i=0;i<mask.length;i++)mask[i]=data[i*4+3]>=128?1:0;
  const toSolid=distance(mask,w,h,1),toClear=distance(mask,w,h,0);
  const row={tier,id:s.id,width:w,height:h,keyCandidates:0,darkExempt:0,alpha0Exempt:0,alpha0AlsoDark:0,failures:[],normal:{solidPixels:0,zMin:1,zMax:-1,nonPositive:0},bruteChecks:0,bruteMismatches:0};
  for(let i=0;i<mask.length;i++){
   const z=n[i*4+2]*2/255-1;
   if(mask[i]){row.normal.solidPixels++;row.normal.zMin=Math.min(row.normal.zMin,z);row.normal.zMax=Math.max(row.normal.zMax,z);if(z<=0)row.normal.nonPositive++;}
   if(!(mask[i]?toClear[i]<=2:toSolid[i]<=(tier==='high'?8:4)))continue;
   const [r,g,b,a]=data.subarray(i*4,i*4+4);if(!keylike(r,g,b,s.key))continue;
   row.keyCandidates++;
   const luma=(.2126*r+.7152*g+.0722*b)/255,v=Math.max(r,g,b)/255;
   const transparent=a===0&&toSolid[i]>=3&&luma<.2;
   if(v<.25){row.darkExempt++;if(transparent)row.alpha0AlsoDark++;continue;}
   if(transparent){row.alpha0Exempt++;continue;}
   const x=i%w,y=Math.floor(i/w),pixel={xy:[x,y],rgba:[r,g,b,a],atlasXY:[rect[0]+x,rect[1]+y],distanceToSolid:toSolid[i],distanceToClear:toClear[i],v,luma,cutoffRetained:a>=128};
   row.failures.push(pixel);allFailure.push({tier,id:s.id,...pixel});
  }
  // Cross-check exact distances near every candidate and a fixed sample against exhaustive neighborhoods.
  for(let i=0;i<mask.length;i+=997){const x=i%w,y=Math.floor(i/w);for(const target of [0,1]){const d=target?toSolid[i]:toClear[i];if(d>9)continue;row.bruteChecks++;if(d!==bruteDistance(mask,w,h,x,y,target))row.bruteMismatches++;}}
  for(const p of row.failures){const [x,y]=p.xy;row.bruteChecks++;if(toSolid[y*w+x]!==bruteDistance(mask,w,h,x,y,1))row.bruteMismatches++;}
  const expected=q95.sprites.find(v=>v.id===s.id)[tier];
  row.reportCountsMatch=row.failures.length===expected.count&&row.darkExempt===expected.darkExempt&&row.alpha0Exempt===expected.transparentExempt;
  for(const k of ['keyCandidates','darkExempt','alpha0Exempt','alpha0AlsoDark','bruteChecks','bruteMismatches'])sums[k]+=row[k];
  sums.failures+=row.failures.length;sums.cutoffRetained+=row.failures.filter(p=>p.cutoffRetained).length;
  result.sprites.push(row);raws.set(tier+':'+s.id,{data,w,h});
 }
 result.totals[tier]=sums;
}
function signatures(groups){return groups.flatMap(g=>g.pixels.map(p=>`${g.tier}/${g.id}/${p.xy.join(',')}/${p.rgba.join(',')}`)).sort();}
const actual=allFailure.map(p=>`${p.tier}/${p.id}/${p.xy.join(',')}/${p.rgba.join(',')}`).sort();
result.checks.exactManifestPixels=JSON.stringify(actual)===JSON.stringify(signatures(manifest.build.edgeReview.failures));
result.checks.exactReportPixels=JSON.stringify(actual)===JSON.stringify(signatures(prior.failures));
result.checks.allCountsMatch=result.sprites.every(s=>s.reportCountsMatch);
result.checks.distancesBruteMatch=result.sprites.every(s=>s.bruteMismatches===0);
result.sources=manifest.sprites.map(s=>({id:s.id,source:s.source,sha256:hash(fs.readFileSync(path.join(tree,'art-src',s.source))),expected:s.sha256,shaMatch:hash(fs.readFileSync(path.join(tree,'art-src',s.source)))===s.sha256}));
const bytes=rel=>result.files.find(f=>f.file===rel).bytes;
const high=bytes('meadow/color.high.webp')+bytes('meadow/normal.high.webp')+bytes('meadow/shadow.high.webp'),medium=bytes('meadow/color.medium.webp')+bytes('meadow/normal.medium.webp');
result.budget={unit:'byte (MB=1000000)',scenery:{high,medium,highTarget:2500000,mediumTarget:800000,highOver:high-2500000,mediumOver:medium-800000},reportedTotals:{high:budget.rows.high.total,medium:budget.rows.medium.total,starter:budget.starter},hardCaps:{high:16000000,medium:9000000,starter:3500000},reportedMissing:budget.missing,sceneryMatchesReport:high===budget.rows.high.scenery&&medium===budget.rows.medium.scenery};
result.allFailure=allFailure;
const measurementsPath=path.join(work,pending?'measurements-pending.json':'measurements.json');
fs.writeFileSync(measurementsPath,JSON.stringify(result,null,2));
console.log(JSON.stringify({totals:result.totals,checks:result.checks,budget:result.budget}));
if(pending){
 const projection=read(path.join(root,'docs/codex-queue/199/budget-projection.json'));
 result.budget.sceneryMatchesReport=high===projection.pendingScenery.high&&medium===projection.pendingScenery.medium;
 result.budget.pendingProjection={high:budget.rows.high.total-budget.rows.high.scenery+high,medium:budget.rows.medium.total-budget.rows.medium.scenery+medium,starter:budget.starter-budget.rows.medium.scenery+medium,additionalHigh:high-budget.rows.high.scenery,additionalMedium:medium-budget.rows.medium.scenery};
 result.budget.projectionMatchesReport=result.budget.pendingProjection.high===projection.pendingTotal.high&&result.budget.pendingProjection.medium===projection.pendingTotal.medium&&result.budget.pendingProjection.starter===projection.pendingStarter;
 fs.writeFileSync(measurementsPath,JSON.stringify(result,null,2));
 process.exit(0);
}

// Derived inspection sheets: raw compositing only; no image generation or source changes.
const font='/System/Library/Fonts/Menlo.ttc';
function label(file,text,width,height){run([file,'-background','#18242b','-gravity','northwest','-splice',`0x${height}`,'-font',font,'-pointsize','13','-fill','white','-annotate','+6+3',text,'-gravity','northwest','-extent',`${width}x${height+parseInt(run(['identify','-format','%h',file]).toString())}`,file]);}
function saveRaw(name,data,w,h){const file=path.join(work,name+'.rgba');fs.writeFileSync(file,data);return ['-size',`${w}x${h}`,'-depth','8','rgba:'+file];}
function alphaMode(data,cutoff){const o=Buffer.from(data);if(cutoff)for(let i=3;i<o.length;i+=4)o[i]=o[i]>=128?255:0;return o;}
const rows=[];
for(let j=0;j<allFailure.length;j++){
 const p=allFailure[j],r=raws.get(p.tier+':'+p.id),[x,y]=p.xy;
 const ww=24,hh=24,xx=Math.max(0,Math.min(r.w-ww,x-12)),yy=Math.max(0,Math.min(r.h-hh,y-12));
 const c=crop(r.data,r.w,[xx,yy,xx+ww,yy+hh]);const panels=[];
 for(const [mode,cutoff] of [['blend',false],['cutoff',true]])for(const bg of ['#3f5a48','#101820']){
  const file=path.join(work,`edge-${j}-${mode}-${bg.slice(1)}.png`);
  run([...saveRaw(`crop-${j}-${mode}`,alphaMode(c.data,cutoff),ww,hh),'-background',bg,'-alpha','remove','-filter','point','-resize','400%','-stroke','#f0d97c','-strokewidth','1','-fill','none','-draw',`rectangle ${(x-xx)*4-1},${(y-yy)*4-1} ${(x-xx)*4+4},${(y-yy)*4+4}`,file]);panels.push(file);
 }
 const file=path.join(work,`edge-row-${j}.png`);run([...panels,'+append','-background','#18242b','-gravity','northwest','-extent','760x96',file]);
 label(file,`${j+1}. ${p.id} ${p.tier} [${x},${y}] A=${p.rgba[3]} RGBA=${p.rgba.join(',')}\n    blend grass/dark         cutoff .5 grass/dark`,760,38);rows.push(file);
}
const x4=path.join(root,'docs/codex-queue/231/edges-x4.jpg');
run([...rows,'-append','-quality','86',x4]);

// Camera projection estimate at the look point: fov38, home58m, closest22m; 1080 CSS pixels tall.
const viewportH=1080,fov=38,distances=[58,22],scaleRows=[];
const pitch=55,tilt=pitch*.4,verticalFactor=Math.cos((pitch-tilt)*Math.PI/180);
result.scaleEstimate={viewportHeightCssPx:viewportH,fovDeg:fov,distancesM:distances,pitchDeg:pitch,billboardTiltDeg:tilt,verticalForeshortening:verticalFactor,designTiltFractionRange:[.3,.5],verticalFactorRange:[Math.cos(pitch*.7*Math.PI/180),Math.cos(pitch*.5*Math.PI/180)],assumptions:'Billboard trục đứng ngả 0,4*pitch theo TK23.10 dòng2727 (thiết kế 0,3–0,5), tâm ở look point, scale=1, tuyến tính hóa projection tại tâm; không mô phỏng perspective theo chiều cao. Camera FOV38, pitch55, zoom58/22m; 1080 CSS px. Bộ lọc Lanczos chỉ là proxy; không mô phỏng WebGL mipmap/anisotropy, lighting, dither, terrain hoặc postprocessing. Không phải capture runtime.',entries:[]};
for(const group of manifest.build.edgeReview.failures){
 const r=raws.get(group.tier+':'+group.id),s=manifest.sprites.find(s=>s.id===group.id),panels=[];
 const footprints=[];
 for(const d of distances){
  const pxPerM=viewportH/(2*d*Math.tan(fov*Math.PI/360)),w=Math.round(s.sizeM[0]*pxPerM),h=Math.round(s.sizeM[1]*pxPerM*verticalFactor),factor=w/r.w;
  footprints.push({distanceM:d,widthPx:w,heightPx:h,texturePixelCssPxX:factor,texturePixelCssPxY:h/r.h});
  for(const bg of ['#3f5a48','#101820']){
   // Resize RGBA first, apply cutoff afterward, as alpha test happens after texture sampling.
   const resized=run([...saveRaw(`scale-src-${group.tier}-${group.id}`,r.data,r.w,r.h),'-filter','Lanczos','-resize',`${w}x${h}!`,'-depth','8','rgba:-']);
   const filtered=alphaMode(resized,true);
   // Use 64x64 real-resolution crops centered on each declared pixel. No enlargement.
   for(let k=0;k<group.pixels.length;k++){
    const p=group.pixels[k],cx=Math.round((p.xy[0]+.5)*w/r.w),cy=Math.round((p.xy[1]+.5)*h/r.h),xx=Math.max(0,Math.min(w-64,cx-32)),yy=Math.max(0,Math.min(h-64,cy-32));
    const c=crop(filtered,w,[xx,yy,xx+64,yy+64]),file=path.join(work,`scale-${group.tier}-${group.id}-${d}-${bg.slice(1)}-${k}.png`);
    run([...saveRaw(`scale-crop-${group.tier}-${group.id}-${d}-${bg.slice(1)}-${k}`,c.data,64,64),'-background',bg,'-alpha','remove','-background','#18242b','-gravity','center','-extent','78x64',file]);
    panels.push(file);
   }
  }
 }
 const file=path.join(work,`scale-row-${group.tier}-${group.id}.png`);run([...panels,'+append','-background','#18242b','-gravity','northwest','-extent',`${Math.max(1248,panels.length*78)}x64`,file]);
 label(file,`${group.id} ${group.tier}: ${group.pixels.map(p=>`[${p.xy}] A${p.rgba[3]}`).join(' | ')}\n58m grass then dark; 22m grass then dark; each patch 64px at 1:1; filtered then cutoff .5`,Math.max(1248,panels.length*78),38);scaleRows.push(file);
 result.scaleEstimate.entries.push({tier:group.tier,id:group.id,footprints});
}
const scaleOut=path.join(root,'docs/codex-queue/231/edges-scale.jpg');run([...scaleRows,'-append','-quality','88',scaleOut]);
result.sheets=[x4,scaleOut].map(p=>({path:path.relative(root,p),bytes:fs.statSync(p).size,sha256:hash(fs.readFileSync(p))}));
fs.writeFileSync(measurementsPath,JSON.stringify(result,null,2));
console.log('sheets',result.sheets);
